package com.vignesh.focuslist.ui.component

import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * The Inbox mascot: the cat sitting upright.
 *
 * Inbox is the screen the user is about to put something into, so the cat is
 * attentive rather than resting. It is also the tallest of the three, which is
 * what a sitting cat should be next to a lying one.
 *
 * Exported from the board, node `1076:5773`. The five poses share one scale factor
 * rather than a common width or height: a cat sitting is taller than the same
 * cat lying down, and normalising either dimension would have made it read as
 * two differently sized animals. [MascotImage] explains why the paths are built
 * in Kotlin and which colour role each tone takes.
 */
@Composable
internal fun InboxMascot(modifier: Modifier = Modifier) {
    MascotImage(
        width = MascotWidth,
        height = MascotHeight,
        modifier = modifier,
        build = ::catSitting
    )
}

private const val MascotWidth = 189.75f
private const val MascotHeight = 172.7f

private fun catSitting(light: Color, mid: Color, dark: Color): ImageVector =
    ImageVector.Builder(
        name = "InboxCatSitting",
        defaultWidth = MascotWidth.dp,
        defaultHeight = MascotHeight.dp,
        viewportWidth = 520.848f,
        viewportHeight = 474.073f
    )
        .addPath(
            pathData = addPathNodes(GroundShadow),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Body),
            fill = SolidColor(light)
        )
        .addPath(
            pathData = addPathNodes(Shading),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(Nose),
            fill = SolidColor(mid)
        )
        .addPath(
            pathData = addPathNodes(EyeLeft),
            fill = SolidColor(dark)
        )
        .addPath(
            pathData = addPathNodes(EyeRight),
            fill = SolidColor(dark)
        )
        .build()

